class Solution:
  def longestWord(self, words: list[str]) -> str:
    root = {}

    for word in words:
      node = root
      for c in word:
        if c not in node:
          node[c] = {}
        node = node[c]
      node['word'] = word

    def dfs(node: dict) -> str:
      ans = node['word'] if 'word' in node else ''

      for child in node:
        if child != 'word' and 'word' in node[child]:
          childWord = dfs(node[child])
          if len(childWord) > len(ans) or (
                  len(childWord) == len(ans) and childWord < ans):
            ans = childWord

      return ans

    return dfs(root)

